</div>
<a class="ml-space-md bg-on-primary text-primary px-space-sm py-space-2xs font-label-caps text-label-caps uppercase font-bold hover:bg-surface-variant transition-colors" href="{{ route('cart') }}">VIEW BAG</a>
</div>
</div>
<script>
  const csrfMeta = document.createElement('meta');
  csrfMeta.name = 'csrf-token';
  csrfMeta.content = @json(csrf_token());
  document.head.appendChild(csrfMeta);

  // Add to Bag Micro-interaction
  function handleAddToCart(itemName, itemPrice) {
    const toast = document.getElementById('quick-cart-toast');
    const titleEl = document.getElementById('toast-title');
    const priceEl = document.getElementById('toast-price');

    if (toast && titleEl && priceEl) {
      titleEl.innerText = itemName.toUpperCase() + ' ADDED';
      priceEl.innerText = itemPrice + ' • READY FOR DISPATCH';
      
      toast.classList.remove('translate-y-32');
      toast.classList.add('translate-y-0');

      setTimeout(() => {
        toast.classList.remove('translate-y-0');
        toast.classList.add('translate-y-32');
      }, 4000);
    }
  }

  // Interactive Size Buttons Active Toggle
  document.querySelectorAll('.size-btn').forEach(btn => {
    btn.addEventListener('click', function() {
      const parent = this.parentElement;
      parent.querySelectorAll('.size-btn').forEach(b => {
        b.classList.remove('bg-primary', 'text-on-primary');
        b.classList.add('bg-surface-container', 'text-on-surface');
      });
      this.classList.remove('bg-surface-container', 'text-on-surface');
      this.classList.add('bg-primary', 'text-on-primary');
    });
  });

  // Newsletter Form Feedback
  function handleNewsletter(event) {
    event.preventDefault();
    const toast = document.getElementById('newsletter-toast');
    const input = document.getElementById('contact-input');
    if (toast && input) {
      toast.classList.remove('hidden');
      input.value = '';
    }
  }

  // Keep public catalog cards in sync with the admin inventory editor.
  const managedInventory = @json($inventory);
  const productImageFallbacks = {
    'k-01-structural-boxy-tee': @json(asset('images/products/k-07-raw-cut-box-tee.png')),
    'brutalist-monolith-cuff-ring-set': @json(asset('images/products/k-11-modular-chest-harness.png')),
  };
  document.querySelectorAll('[data-product-slug] img').forEach((image) => {
    const fallback = productImageFallbacks[image.closest('[data-product-slug]')?.dataset.productSlug];
    if (!fallback) return;
    const useFallback = () => {
      if (image.src !== fallback) image.src = fallback;
    };
    image.addEventListener('error', useFallback, { once: true });
    if (image.complete && image.naturalWidth === 0) useFallback();
  });
  document.querySelectorAll('header img').forEach((image) => {
    if (!/KRUZO/i.test(image.alt)) return;
      const replaceBrokenLogo = () => {
        if (image.naturalWidth !== 0) return;
      if (!image.src.endsWith('/images/kruzo-logo.svg')) image.src = '/images/kruzo-logo.svg';
      };
    image.addEventListener('error', replaceBrokenLogo, { once: true });
    if (image.complete && image.naturalWidth === 0) replaceBrokenLogo();
  });
  const shopRoute = @json(route('shop'));
  const collectionLinks = {
    'shop-all': shopRoute,
    'new-arrivals': `${shopRoute}?sort=newest`,
    'oversized-shirts': `${shopRoute}?category=oversized`,
    'heavyweight-basics': `${shopRoute}?category=heavyweight`,
    'architectural-accessories': `${shopRoute}?category=accessories`,
  };
  Object.entries(collectionLinks).forEach(([path, url]) => {
    document.querySelectorAll(`[data-path="${path}"]`).forEach((link) => {
      link.href = url;
      link.addEventListener('click', (event) => {
        event.preventDefault();
        window.location.assign(url);
      });
    });
  });
  const homeBagButton = [...document.querySelectorAll('header button')]
    .find((button) => /BAG \(/i.test(button.textContent));
  if (homeBagButton) {
    const homeBagLink = document.createElement('a');
    homeBagLink.href = @json(route('cart'));
    homeBagLink.className = homeBagButton.className;
    homeBagLink.innerHTML = homeBagButton.innerHTML;
    homeBagLink.setAttribute('data-path', 'cart');
    homeBagLink.onclick = () => {
      window.location.assign(@json(route('cart')));
      return false;
    };
    homeBagButton.replaceWith(homeBagLink);
  }
  document.querySelectorAll('[data-path="lookbook-ss25"]').forEach((link) => {
    link.href = @json(route('lookbook'));
  });
  document.querySelectorAll('a').forEach((link) => {
    if (link.textContent.trim().toUpperCase() === 'EXPLORE LOOKBOOK') {
      link.href = @json(route('lookbook'));
    }
  });
  const contactFeedbackLink = document.createElement('a');
  contactFeedbackLink.href = @json(route('contact'));
  contactFeedbackLink.textContent = 'CONTACT / FEEDBACK';
  contactFeedbackLink.className = 'font-label-caps text-label-caps uppercase tracking-widest font-bold text-on-surface-variant hover:text-on-surface transition-colors py-space-xs';
  document.querySelector('header nav')?.append(contactFeedbackLink);
  const managedPrice = (value) => '₱' + Number(value).toLocaleString('en-PH', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  document.querySelectorAll('[data-product-slug]').forEach(card => {
    const item = managedInventory[card.dataset.productSlug];
    if (!item) { card.style.display = 'none'; return; }
    card.querySelector('h3')?.replaceChildren(document.createTextNode(item.name));
    if (item.image) card.querySelector('img')?.setAttribute('src', item.image);
    card.querySelectorAll('.font-price-lg').forEach(price => price.textContent = managedPrice(item.price));
    card.querySelectorAll('button[onclick*="handleAddToCart"]').forEach(button => {
      button.setAttribute('onclick', `handleAddToCart(${JSON.stringify(item.name)}, ${JSON.stringify(managedPrice(item.price))})`);
    });
    card.dataset.price = item.price;
  });

  // Category Filter Pill Simulation
  document.querySelectorAll('#category-filters button').forEach(pill => {
    pill.addEventListener('click', function() {
      document.querySelectorAll('#category-filters button').forEach(b => {
        b.classList.remove('bg-primary', 'text-on-primary');
        b.classList.add('bg-surface-container', 'text-on-surface-variant');
      });
      this.classList.remove('bg-surface-container', 'text-on-surface-variant');
      this.classList.add('bg-primary', 'text-on-primary');
    });
  });
</script></main><footer class="w-full bg-surface-container-lowest border-t border-surface-container-highest mt-space-4xl"><div class="max-w-max-width mx-auto px-gutter-desktop py-space-3xl"><div class="grid grid-cols-1 md:grid-cols-12 gap-space-2xl pb-space-2xl border-b border-surface-container-highest"><div class="md:col-span-5 flex flex-col justify-between pr-space-lg"><div class="space-y-space-md"><div class="flex items-center"><img alt="KRUZO Architectural Geometric Logo" class="h-8 w-auto object-contain" src="https://lh3.googleusercontent.com/aida/AEtjO1Xl5Ai1AMcRNxJxGyvUT5R8CfFImqwT8ChuQNxqVStwZW0Tjk45G863yiClacnu9Ogsd_fLpK_IL7u2FrXw4l2uhykVwCgacR0_vmKI-NQN-WxVks15fKeUm1ifAMrDtPX4b0VT8yALGChnWB3y0CR5-LYstq9_1Sg-loh_p0RDjODjO5OYjKtlDFu225ZSde-kn_OIs4-BtA1Ijg8g3IEifvj2IOvVpqTE4bhxQTkiiJMW0woIIfTc8OA"></div><p class="font-body-md text-body-md text-on-surface-variant max-w-sm">Elevated architectural garments engineered for the tropical climate. Built with brutalist discipline and tailored precision in Metro Manila.</p></div><div class="pt-space-xl"><span class="font-label-caps text-label-caps uppercase text-secondary block mb-space-xs">MANILA FLAGSHIP HUB</span><p class="font-body-md text-body-md text-on-surface">Chino Roces Ave, Makati, Metro Manila, Philippines</p></div></div><div class="md:col-span-4 space-y-space-md"><span class="font-label-caps text-label-caps uppercase text-primary tracking-widest block">CUSTOMER CARE &amp; LOGISTICS</span><ul class="space-y-space-xs"><li class="font-body-md text-body-md text-on-surface-variant">Metro Manila &amp; Nationwide Delivery (LBC &amp; J&amp;T Express)</li><li class="font-body-md text-body-md text-on-surface-variant">Cash on Delivery (COD) Available Nationwide</li><li class="font-body-md text-body-md text-on-surface-variant">GCash / Maya / Card Direct Checkout</li><li class="font-body-md text-body-md text-on-surface-variant">Instant Courier Fulfillment via Grab / Lalamove</li><li class="font-body-md text-body-md tex